			namespace: "production",
			pageToken: "foo",
			listError: errors.New("pageToken is not valid: \"foo\""),
		},
		{
			name:      "Invalid Offset",
			namespace: "production",
			pageToken: "60000",
			listError: errors.New("invalid offset: 60000"),
		},
