	}
}

#FlagBoolean: {
	type: "BOOLEAN_FLAG_TYPE"
	rollouts: [...{
		description?: string
		#Rollout
	}]
}

#Variant: {
	key:          string & =~"^.+$"
	name:         string & =~"^.+$"
	description?: string
	attachment:   {...} | *null
}

#RuleSegment: {
	keys: [...string]
	operator: "OR_SEGMENT_OPERATOR" | "AND_SEGMENT_OPERATOR" | *null
}

#Rule: {
	segment: string & =~"^[-_,A-Za-z0-9]+$" | #RuleSegment
	rank?:   int
	distributions: [...#Distribution]
}

#Distribution: {
	variant: string & =~"^.+$"
	rollout: >=0 & <=100
}

#RolloutSegment: {key: string & =~"^[-_,A-Za-z0-9]+$"} | {keys: [...string]}

#Rollout: {
	segment: {
		#RolloutSegment
		operator: "OR_SEGMENT_OPERATOR" | "AND_SEGMENT_OPERATOR" | *null
		value:    bool
	}
} | {
	threshold: {
		percentage: float
		value:      bool
	}
